<template>
  <div :class="[meta_field.class, extraClass]">
    <div class="row full-width q-pa-xs">
      <template v-if="meta_field.before" class="col">
        <component
          v-bind="meta_field.before.props"
          :is="meta_field.before.component"
          v-html="meta_field.before.innerContent"
        />
      </template>
      <div class="col">
        <label
          class="row items-center"
          v-if="
            ['outer', 'inline', undefined].includes(meta_field.label_style) &&
            meta_field.type !== 'FILE' &&
            meta_field.type !== 'file'
          "
          style="white-space: nowrap"
        >
          {{ meta_field.title ? $t(meta_field.title) : '&nbsp;' }}
          <span class="text-red">&nbsp;{{ asterisk }}</span>
          <q-icon
            v-if="meta_field.labelHint"
            name="info"
            style="font-size: large; color: orange; padding-bottom: 5px"
          >
            <q-tooltip>{{ $t(meta_field.labelHint) }}</q-tooltip>
          </q-icon>
        </label>
        <div
          :class="[
            'supplier-field-control-row',
            meta_field.after && 'supplier-field-control-row--with-action',
          ]"
          :data-testid="
            meta_field.after ? 'supplier-field-control-row' : undefined
          "
        >
          <component
            :is="fieldComponent"
            :meta_field="meta_field"
            :name="props.meta_field.field_name"
            :type="
              meta_field.type === 'group-checkbox'
                ? 'checkbox'
                : meta_field.type
            "
            :translationKey="props.translationKey"
            :disable="disabled || meta_field.disable || false"
            :readonly="readonly || meta_field.readonly || false"
            :model-value="modelValue"
            :stack-label="meta_field.label_style === 'stack'"
            @update:model-value="onUpdateValue($event)"
            dense
            hide-bottom-space
            reactive-rule
            :label-slot="
              !['outer', 'inline', undefined].includes(meta_field.label_style)
            "
            :asterisk="asterisk"
            :isOuter="
              ['outer', 'inline', undefined].includes(meta_field.label_style)
            "
            :rules="[
              ...(meta_field.required
                ? [
                    (val: string) =>
                      !!val ||
                      $t(
                        meta_field.requiredMessageKey
                          ? $t(
                              `${props.translationKey}.error.${meta_field.requiredMessageKey}`,
                            )
                          : 'field_required',
                      ),
                  ]
                : []),
              ...(meta_field.type === 'email'
                ? [
                    (val: string) =>
                      emailRule(val) ||
                      $t(`${props.translationKey}.error.email_err`),
                  ]
                : []),
              ...(meta_field.rules?.map((rule) => {
                return (value: any) =>
                  rule.rule(value) ||
                  $t(`${props.translationKey}.error.${rule.messageKey}`);
              }) || []),
            ]"
          />
          <template v-if="meta_field.after">
            <div
              class="supplier-field-action"
              data-testid="supplier-field-action"
            >
              <component
                v-bind="meta_field.after.props"
                :disabled="
                  meta_field.after?.readonly ||
                  (btnVisible && (readonly || meta_field.readonly))
                "
                :is="meta_field.after.component"
                :icon="innerHtml"
                :aria-label="innerHtml === 'remove' ? 'Remove row' : 'Add row'"
                @click="afterClick"
              />
            </div>
          </template>
        </div>
      </div>
    </div>
  </div>
</template>
<script setup lang="ts">
import { dynamicObj } from 'pages/assets';
import { emailRule } from 'src/supplier/utils/validator';
import { computed, onMounted, watch, ref, nextTick } from 'vue';
import { FieldValue, MetaField, MetaKeys } from 'src/supplier/types/meta';
import InputField from 'src/supplier/components/dynamic/form/InputField.vue';
import OptionField from 'src/supplier/components/dynamic/form/OptionField.vue';
import SelectField from 'src/supplier/components/dynamic/form/SelectField.vue';
import CheckboxField from 'src/supplier/components/dynamic/form/CheckboxField.vue';
import FileField from 'src/supplier/components/dynamic/form/FileField.vue';
import Note from 'src/supplier/components/dynamic/form/Note.vue';
import Radio from 'src/supplier/components/dynamic/form/Radio.vue';
import AssignedUser from 'src/supplier/components/dynamic/form/AssignedUser.vue';
import { useSupplierLayoutsStore } from 'src/store/main';
import { storeToRefs } from 'pinia';
import { isEmpty } from 'src/supplier/utils';
import * as constant from 'src/supplier/constant';
import type { Component } from 'vue';
import './RepeatableSectionAction.css';
type FieldProps = {
  meta_field: any;
  modelValue: FieldValue<dynamicObj, MetaKeys<dynamicObj>>;
  isError?: boolean;
  errorMessage?: string;
  readonly?: boolean;
  disabled?: boolean;
  translationKey?: string;
  afterClick?: () => void;
  innerHtml?: any;
  btnVisible?: boolean;
  enableMetadata?: boolean;
};
const supplierLayoutStore = useSupplierLayoutsStore();
const {
  formLayout,
  formConfigure,
  renderComponent,
  layout_type,
  originalFormMultiple,
} = storeToRefs(supplierLayoutStore);

const props = withDefaults(defineProps<FieldProps>(), {
  translationKey: 'supplier_register_form',
});

const emit = defineEmits(['update:modelValue']);

const { meta_field, afterClick, innerHtml, btnVisible, enableMetadata } = props;

const fieldMetaData = ref([]);

const isOuter = ['outer', 'inline', undefined].includes(meta_field.label_style);

const extraClass =
  meta_field.label_style === 'inline' ? 'flex q-col-gutter-lg' : '';
const asterisk = computed(() => {
  return props.meta_field.required ? '*' : '';
});

const onUpdateValue = (event: Event) => {
  emit('update:modelValue', event);
  if (enableMetadata) {
    processFieldMetaData();
  }
};

onMounted(() => {
  if (enableMetadata) {
    let fieldMetaDataValue = meta_field.calculation_formula;
    if (fieldMetaDataValue) {
      try {
        fieldMetaDataValue = JSON.parse(fieldMetaDataValue);
        fieldMetaData.value = fieldMetaDataValue;
      } catch (error) {
        logError(
          'Error parsing calculation_formula on field : {{' +
            meta_field.field_name +
            '}}',
          error,
        );
      }
    }
    nextTick(() => {
      processFieldMetaData();
    });
  }
});
const processFieldMetaData = () => {
  if (fieldMetaData.value.length > 0) {
    fieldMetaData.value.forEach(evaluateCondition);
  }
};

const getValueByPath = (obj: dynamicObj, path: string) => {
  return path
    .split('.')
    .reduce((acc, part) => acc && acc[part], obj) as unknown as string;
};
const resolvedValue = (
  data: dynamicObj,
  action: dynamicObj,
): string | string[] => {
  try {
    let value = '' as any;
    //if value path isn't define return value
    if (!action.value_path) {
      return action.value as string;
    }
    if (Array.isArray(action.value_path)) {
      //if value path is array then get value by path and return array of values
      value = action.value_path.map((path: string) =>
        getValueByPath(data, path),
      );
    } else {
      //get value by path
      value = getValueByPath(data, action.value_path);
    }
    if (action.seperator) {
      //split value by seperator and return value by index "Ex: 110_N90 => [110,N90]"
      value = value.split(action.seperator);
      if (value.length > 0) {
        value = value[action.index];
      }
    }
    return value as string | string[];
  } catch (error) {
    logInfo(error, 'RESOLVE_VALUE_ERROR:' + action.value_path);
  }
};
const setValueByPath = (
  obj: dynamicObj,
  path: string,
  value: any,
  action: dynamicObj,
  view_side: string,
) => {
  const parts = path.split('.');
  const last = parts.pop() as string;

  const target = parts.reduce(
    (acc, part) => (acc[part] = acc[part] || {}),
    obj,
  );
  if (
    (view_side === 'supplier_view' && layout_type.value === 'supplier_user') ||
    (view_side === 'management_view' &&
      layout_type.value === 'supplier_management') ||
    !view_side
  ) {
    target[last] = formatValue(value, action.format);
  }
};
const startWithString = (contextValue: any, value: any): boolean => {
  let condition = false;
  if (contextValue === undefined) {
    return false;
  }
  condition = contextValue.startsWith(value);
  return condition;
};
const notStartWithString = (contextValue: any, value: any): boolean => {
  let condition = false;
  if (contextValue === undefined) {
    condition = true;
    return condition;
  }
  condition = !contextValue.startsWith(value);
  return condition;
};
const formatValue = (value: string | number, format: string) => {
  if (!format) return value;
  if (format === 'date') {
    return new Date(value);
  }
  if (format === 'int') {
    return parseInt(String(value));
  }
  if (format === 'float') {
    return parseFloat(String(value));
  }
  if (format === 'string') {
    return String(value);
  }
  return value;
};
const setRulAddressValidation = (
  obj: dynamicObj,
  path: string,
  basedKey: string,
  value: any,
  layout: any,
  key: string,
) => {
  const parts = path.split('.');
  const last = parts.pop() as string;

  const target = parts.reduce(
    (acc, part) => (acc[part] = acc[part] || {}),
    obj,
  );
  if (Array.isArray(target[last])) {
    const existingArray = target[last];
    const matchingGroup = layout.find((group: any) => group.name === path);
    if (matchingGroup) {
      matchingGroup.rows.map((row: any) => {
        row.map((field: any) => {
          if (field.field_name === basedKey) {
            field.rules = [];
            value.forEach((val: any) => {
              const messageKey =
                val === '1'
                  ? 'no_physical_address_err'
                  : val === '3'
                    ? 'pickup_address_type_err'
                    : 'no_remittance_address_err';
              field.rules.push({
                key: basedKey,

                rule: () =>
                  existingArray.some(
                    (address: any) => address?.[basedKey] == val,
                  ),
                messageKey: messageKey, // Static message key; adjust as needed
              });
            });
          }
        });
      });
    }
  }
};
const setArrayValueByPath = (
  obj: dynamicObj,
  path: string,
  basedKey: string,
  value: any,
  layout: any,
  view_side: string,
) => {
  const parts = path.split('.');
  const last = parts.pop() as string;

  const target = parts.reduce(
    (acc, part) => (acc[part] = acc[part] || {}),
    obj,
  );

  if (Array.isArray(target[last])) {
    const existingArray = target[last].filter(
      (val: any, index: number) => typeof val !== 'object' || !isEmpty(val),
    );
    value.forEach((val: any) => {
      const matchIndex = existingArray.findIndex(
        (item: any) => item[basedKey] == val[basedKey],
      );
      if (matchIndex === -1) {
        existingArray.unshift(val);
        const matchingGroup = layout.find((group: any) => group.name === path);
        if (matchingGroup) {
          matchingGroup.rows.push(
            originalFormMultiple.value.get(matchingGroup.name),
          );
        }
      }
    });
    if (
      (view_side === 'supplier_view' &&
        layout_type.value === 'supplier_user') ||
      (view_side === 'management_view' &&
        layout_type.value === 'supplier_management') ||
      !view_side
    ) {
      target[last] = existingArray;
    }
  }
};
const setVisibleSection = (
  data: dynamicObj,
  layout: dynamicObj[],
  key: string,
  value: any,
  action: any,
) => {
  const { view_side } = action;
  if (
    (view_side === 'supplier_view' && layout_type.value === 'supplier_user') ||
    (view_side === 'management_view' &&
      layout_type.value === 'supplier_management') ||
    !view_side
  ) {
    let section = layout.find((item: any) => item.name === key) as any;
    if (section) {
      Object.keys(value).forEach((keys) => {
        section[keys] = value[keys];
      });
    }
  }
};
const setValueWithOption = (
  data: dynamicObj,
  layout: dynamicObj[],
  key: string,
  value: string[],
  action: any,
) => {
  let options = [];
  //fetch options from layout
  action?.option_path?.forEach((element) => {
    const section = layout.find(
      (section: any) => section.name === element.section,
    );
    if (section) {
      const rows = section.rows;
      const object = rows.find(
        (row: any) => row.field_name === element.field_name,
      );
      options = options.concat(JSON.parse(JSON.stringify(object.options)));
    }
  });
  if (action.load_constant) {
    action?.constant_keys.forEach((key: string) => {
      const option = constant[key] as any[];
      if (option) {
        options = options.concat(option);
      }
    });
  }
  //compile value with options
  let compiledValue = '';
  value.forEach((val: any, index: number) => {
    if (val === undefined) val = '';
    const option = options.find(
      (option: any) => option[action.search_key] === val,
    );
    if (option) {
      compiledValue +=
        option[action.value_key] +
        (index != value.length ? action.separator : '');
    }
  });

  //set compiled value to key
  setValueByPath(data, key, compiledValue, action, action?.view_side);
};
const setMetedataArrayBySearch = (
  layout: dynamicObj[],
  action: any,
  data: dynamicObj,
) => {
  const { key, operator, search_key, then_set, view_side, value } = action;
  const updateFieldMetadata = (field: any, properties: any) => {
    Object.keys(properties).forEach((key) => {
      field[key] = properties[key];
    });
  };

  const updateFieldCondition = (fields: any[], then_set: any[]) => {
    return fields.map((field: any) => {
      const condition = then_set.find(
        (condition: any) => field.field_name === condition.key,
      );
      if (condition) {
        updateFieldMetadata(field, condition?.properties);
      }

      return field;
    });
  };

  if (
    (view_side === 'supplier_view' && layout_type.value === 'supplier_user') ||
    (view_side === 'management_view' &&
      layout_type.value === 'supplier_management') ||
    !view_side
  ) {
    const sectionData = data[key];
    sectionData.forEach((item: any, index: number) => {
      let conditionMet = false;
      switch (operator) {
        case '>':
          conditionMet = item[search_key] > value;
          break;
        case '<':
          conditionMet = item[search_key] < value;
          break;
        case '>=':
          conditionMet = item[search_key] >= value;
          break;
        case '<=':
          conditionMet = item[search_key] <= value;
          break;
        case '==':
          conditionMet = item[search_key] == value;
          break;
        case '!=':
          conditionMet = item[search_key] != value;
          break;
        case 'in':
          conditionMet =
            Array.isArray(value) && value.includes(item[search_key]);
          break;
        case 'not in':
          conditionMet =
            Array.isArray(value) && !value.includes(item[search_key]);
        case 'start_with_string':
          conditionMet = startWithString(item[search_key], value);
          break;
        case 'not_start_with_string':
          conditionMet = notStartWithString(item[search_key], value);
          break;
        default:
          logError('Unsupported operator:', operator);
      }
      if (conditionMet) {
        const groupIndex = layout.findIndex(
          (section: any) => section.name === key,
        );
        if (groupIndex !== -1) {
          const row = JSON.parse(
            JSON.stringify(layout[groupIndex]?.rows[index]),
          );
          if (row) {
            const updatedFields = updateFieldCondition(row, then_set);
            layout[groupIndex].rows[index] = updatedFields;
          }
        }
      }
    });
  }
};
const setMetadata = (data: dynamicObj[], action: any) => {
  const { key, value, view_side } = action;
  const updateFieldMetadata = (field: any) => {
    if (
      action.hasOwnProperty('readonly_btn_multi') &&
      field.hasOwnProperty('after')
    ) {
      field['after']['readonly'] = action.readonly_btn_multi;
    }
    Object.keys(value).forEach((keys) => {
      field[keys] = value[keys];
    });
  };

  const updateLayoutField = (
    data: dynamicObj[],
    path: string,
    updateFunc: any,
  ) => {
    data.forEach((group) => {
      if (group.rows) {
        group.rows.forEach((row: any) => {
          if (Array.isArray(row)) {
            row.forEach((field) => {
              if (field.field_name === path || path === 'all') {
                updateFunc(field);
              }
            });
          } else {
            if (row.field_name === path || path === 'all') {
              updateFunc(row);
            }
          }
        });
      }
    });
  };

  if (
    (view_side === 'supplier_view' && layout_type.value === 'supplier_user') ||
    (view_side === 'management_view' &&
      layout_type.value === 'supplier_management') ||
    !view_side
  ) {
    updateLayoutField(data, key, updateFieldMetadata);
  }
};

const setValueByStartCharactor = (
  data: dynamicObj,
  layout: dynamicObj[],
  action: any,
) => {
  const { key, value_path, view_side, charactor } = action;
  const resovle_value = getValueByPath(data, value_path);
  const result = resovle_value.substring(0, charactor);

  const parts = key.split('.');
  const last = parts.pop() as string;

  const target = parts.reduce(
    (acc, part) => (acc[part] = acc[part] || {}),
    data,
  );
  if (
    (view_side === 'supplier_view' && layout_type.value === 'supplier_user') ||
    (view_side === 'management_view' &&
      layout_type.value === 'supplier_management') ||
    !view_side
  ) {
    target[last] = formatValue(result, action.format);
  }
};
const setValueArrayBySearch = (
  data: dynamicObj,
  layout: dynamicObj[],
  action: any,
) => {
  const { key, operator, search_key, then_set, view_side, value } = action;
  const setValueToObject = (then_set: any, item: any) => {
    const prefix_value =
      then_set.prefix && getValueByPath(data, then_set.value_path);
    const suffix_value =
      then_set.suffix && getValueByPath(data, then_set.value_path);

    if (then_set.prefix) {
      item[then_set.key] = prefix_value + then_set.value;
    } else if (then_set.suffix) {
      item[then_set.key] = then_set.value + suffix_value;
    } else {
      item[then_set.key] = then_set.value;
    }
  };
  if (
    (view_side === 'supplier_view' && layout_type.value === 'supplier_user') ||
    (view_side === 'management_view' &&
      layout_type.value === 'supplier_management') ||
    !view_side
  ) {
    const sectionData = data[key];
    sectionData.forEach((item: any, index: number) => {
      let conditionMet = false;
      switch (operator) {
        case '>':
          conditionMet = item[search_key] > value;
          break;
        case '<':
          conditionMet = item[search_key] < value;
          break;
        case '>=':
          conditionMet = item[search_key] >= value;
          break;
        case '<=':
          conditionMet = item[search_key] <= value;
          break;
        case '==':
          conditionMet = item[search_key] == value;
          break;
        case '!=':
          conditionMet = item[search_key] != value;
          break;
        case 'in':
          conditionMet =
            Array.isArray(value) && value.includes(item[search_key]);
          break;
        case 'not in':
          conditionMet =
            Array.isArray(value) && !value.includes(item[search_key]);
        case 'start_with_string':
          conditionMet = startWithString(item[search_key], value);
          break;
        case 'not_start_with_string':
          conditionMet = notStartWithString(item[search_key], value);
          break;
        default:
          logError('Unsupported operator:', operator);
      }
      if (conditionMet) {
        then_set.map((conditionValue: any) => {
          setValueToObject(conditionValue, item);
        });
      }
    });
  }
};
const processAction = (
  action: dynamicObj,
  data: dynamicObj,
  layout: dynamicObj[],
  key: string,
) => {
  let value = resolvedValue(data, action);
  switch (action.type) {
    case 'set_value':
      setValueByPath(data, action.key, value, action, action?.view_side);
      break;
    case 'set_metadata':
      setMetadata(layout, action);
      break;
    case 'set_metadata_array_by_search':
      setMetedataArrayBySearch(layout, action, data);
      break;
    case 'set_array_value':
      setArrayValueByPath(
        data,
        action.key,
        action.based_key,
        action.value,
        layout,
        action?.view_side,
      );
      break;
    case 'set_rule_address_validation':
      setRulAddressValidation(
        data,
        action.key,
        action.based_key,
        action.value,
        layout,
        key,
      );
      break;
    case 'set_value_with_option':
      setValueWithOption(
        data,
        layout,
        action.key,
        Array.isArray(value) ? value : [value],
        action,
      );
      break;
    case 'set_visible_section':
      setVisibleSection(data, layout, action.key, value, action);
      break;
    case 'set_value_by_start_charactor':
      setValueByStartCharactor(data, layout, action);
      break;
    case 'set_value_array_by_search':
      setValueArrayBySearch(data, layout, action);
      break;
    default:
      logError('Unsupported action type:', action.type);
  }
};

const evaluateCondition = (metaDataCondition: dynamicObj) => {
  const { key, operator, value, then, conditions, type } = metaDataCondition;
  const data = formConfigure.value;
  const layout = formLayout.value;
  let conditionMet = false;
  const evaluateSingleCondition = (
    key: string,
    operator: string,
    value: any,
  ) => {
    let contextValue = key ? getValueByPath(data, key) : undefined;
    if (contextValue !== undefined || operator === 'is empty') {
      switch (operator) {
        case '>':
          return contextValue > value;
        case '<':
          return contextValue < value;
        case '>=':
          return contextValue >= value;
        case '<=':
          return contextValue <= value;
        case '==':
          return contextValue == value;
        case '!=':
          return contextValue != value;
        case 'in':
          return Array.isArray(value) && value.includes(contextValue);
        case 'not in':
          return Array.isArray(value) && !value.includes(contextValue);
        case 'is empty':
          return (
            contextValue === '' ||
            contextValue === undefined ||
            contextValue === null
          );
        case 'start_with_string':
          return startWithString(contextValue, value);
        case 'not_start_with_string':
          return notStartWithString(contextValue, value);
        default:
          logError('Unsupported operator:', operator);
          return false;
      }
    } else {
      logError('key not found:', key);
      return false;
    }
  };

  // Handle multiple conditions (if any)
  if (type === 'condition' && Array.isArray(conditions)) {
    if (operator === 'and') {
      conditionMet = conditions.every((cond: any) =>
        evaluateSingleCondition(cond.key, cond.operator, cond.value),
      );
    } else if (operator === 'or') {
      conditionMet = conditions.some((cond: any) =>
        evaluateSingleCondition(cond.key, cond.operator, cond.value),
      );
    } else {
      logError('Unsupported logical operator:', operator);
    }
  } else {
    // Handle single condition case
    conditionMet = evaluateSingleCondition(key, operator, value);
  }
  if (conditionMet) {
    if (Array.isArray(then)) {
      then.map((e: any) => {
        processAction(e, data, layout, key);
      });
    } else {
      processAction(then, data, layout, key);
    }
  }
};

//conditionally choose the component to render
const fieldComponent = computed(() => {
  if (meta_field.type === 'SPECIAL') {
    //use this for now since we only have 1 special field
    return AssignedUser as Component;
  } else if (
    [
      'STRING',
      'NUMBER',
      'TEXTAREA',
      'text',
      'number',
      'password',
      'email',
      'tel',
      'textarea',
    ].includes(meta_field.type)
  )
    return InputField as Component;
  else if (['radio', 'group-checkbox', 'toggle'].includes(meta_field.type))
    return OptionField as Component;
  else if (['SELECT', 'SEARCH', 'select', 'search'].includes(meta_field.type))
    return SelectField as Component;
  else if (['FILE', 'file'].includes(meta_field.type))
    return FileField as Component;
  else if (['checkbox', 'BOOLEAN'].includes(meta_field.type))
    return CheckboxField as Component;
  else if (['NOTE', 'note'].includes(meta_field.type)) {
    return Note as Component;
  } else if (['RADIO'].includes(meta_field.type)) return Radio as Component;
  else return null;
});
</script>
