<template>
  <q-select
    v-bind="props"
    :class="`${additionalClass}`"
    :options="filterOption"
    v-model="model"
    :loading="loading"
    :inline="meta_field.label_style === 'inline'"
    :outlined="
      meta_field.design === 'outlined' ||
      meta_field.design === 'outlined-filled'
    "
    :border-less="meta_field.design === 'borderless'"
    :standout="meta_field.design === 'standout'"
    :filled="meta_field.design === 'filled'"
    :behavior="'default'"
    :hint="meta_field.hint"
    :hide-dropdown-icon="true"
    :default-value="model"
    :use-input="true"
    @filter="filterFn"
    autocomplete=""
    map-options
    emit-value
    hide-hint
    @update:modelValue="
      ($emit('update:modelValue', $event), console.log(model, 'model'))
    "
    @keyup.delete="model = ''"
  >
    <template v-slot:label>
      <span>{{ 'Assigned user' }}</span>
    </template>
    <template v-slot:no-option>
      <q-item>
        <q-item-section class="text-grey"> No results </q-item-section>
      </q-item>
    </template>
  </q-select>
</template>

<script lang="ts">
import { defineComponent, toRaw } from 'vue';
import type { SelectMetaField } from 'src/supplier/types/meta';
import { computed, onMounted, ref } from 'vue';
import { QSelect } from 'quasar';
import { userApiService } from 'src/services';
import type { dynamicObj } from 'src/pages/assets';
type SelectFieldProps = {
  meta_field: any;
  name: string;
  label?: string;
  rules: SelectMetaField['rules'];
  class?: string;
  disable: SelectMetaField['disable'];
  readonly: boolean;
  stackLabel: boolean;
  dense: boolean;
  hideBottomSpace: boolean;
  reactiveRule?: boolean;
  labelSlot?: boolean;
  asterisk?: string;
  isOuter?: boolean;
  hint?: string;
  translationKey: string;
  label_style?: string;
  design?: string;
};
export default defineComponent({
  el: '#app',
  props: {
    meta_field: {
      type: Object as () => SelectFieldProps,
      required: true,
    },
    modelValue: {
      type: String,
    },
  },
  data() {
    return {
      model: '' as string | undefined,
      filterOption: [],
      loading: true,
    };
  },
  async mounted() {
    const res = await userApiService.getUsers();
    this.filterOption = res.map((v: any) => ({
      label: v.name,
      value: v.id.toString(),
    }));
    console.log(this.filterOption, 'filterOption');
    this.model = toRaw(this.modelValue);
    this.loading = false;
  },
  methods: {
    filterFn(val: any, update: any, abort: any) {
      update(() => {
        const needle = val.toLowerCase();
        this.filterOption = this.filterOption.filter(
          (v: any) => v.label.toLowerCase().indexOf(needle) > -1,
        );
      });
    },
  },
  emits: ['update:modelValue'],
  setup(props, { emit }) {
    const outlinedFilled =
      props.meta_field.design === 'outlined-filled' ? 'bg-grey-5' : '';
    const inlineLabel =
      props.meta_field.label_style === 'inline' ? 'flex q-col-gutter-xl' : '';
    const additionalClass = `${outlinedFilled} ${inlineLabel}`;
    return {
      props,
      additionalClass,
    };
  },
});
</script>
