<template>
  <div
    ref="noteTextRef"
    class="note-text"
    v-html="props.meta_field.default_value"
  ></div>
</template>

<script setup lang="ts">
import { ref, onMounted } from 'vue';
import axios from 'axios';
import { getAuthorizationToken } from 'src/pages/APIs';
import { getOrgId } from 'src/utils/organization/org_id_helper';

type NoteFieldProp = {
  meta_field: any;
  modelValue: string;
};

const props = defineProps<NoteFieldProp>();
const emit = defineEmits(['update:modelValue']);

const noteTextRef = ref<HTMLElement | null>(null);
const processedLinks = new Set<HTMLAnchorElement>();

const updateTokenInUrl = (url: string, token: string) => {
  const urlObj = new URL(url);
  urlObj.searchParams.set('token', token);
  return urlObj.toString();
};
const getFileExtension = (url: string): string => {
  const extension = url.split('.').pop();
  return extension ? `.${extension}` : '';
};
const getFileName = (url: string) => {
  const urlObj = new URL(url);
  const path = urlObj.searchParams.get('path') as string;
  const extension = getFileExtension(path);
  const decodedFileName = decodeURIComponent(
    urlObj.pathname.split('/').pop() || 'download',
  );
  return decodedFileName + extension;
};
const downloadBlob = (blob: Blob, filename: string) => {
  const url = window.URL.createObjectURL(blob);
  const a = document.createElement('a');
  a.href = url;
  a.download = filename;
  document.body.appendChild(a);
  a.click();
  document.body.removeChild(a);
  window.URL.revokeObjectURL(url);
};

onMounted(() => {
  if (noteTextRef.value) {
    const links = noteTextRef.value.querySelectorAll('a');
    links.forEach((link) => {
      if (!processedLinks.has(link)) {
        link.addEventListener('click', (event: any) => {
          event.preventDefault();
          (async () => {
            try {
              const newToken = await getAuthorizationToken();
              const updatedUrl = updateTokenInUrl(
                link.href,
                newToken.split(' ')[1],
              );
              const urlObj = new URL(link.href);
              const path = urlObj.searchParams.get('path') as string;

              //Allow non blob files ( images, urls ) and PDFs to always open
              if (path === null || path.endsWith('.pdf')) {
                window.open(updatedUrl, '_blank');
              } else {
                const response = await axios.get(updatedUrl, {
                  params: {
                    org_id: getOrgId(),
                  },
                  responseType: 'blob', // Adjust response type as needed
                });
                const filename = getFileName(link.href);
                downloadBlob(response.data, filename);
              }
            } catch (error) {
              logError({ msg: 'Error fetching file', error: error });
            }
          })();
        });
        processedLinks.add(link);
      }
    });
  }
});
</script>

<style scoped>
.note-text {
  color: var(--primary-color) !important;
}
</style>
