<template>
  <div>
    <div v-if="!props.isOuter" class="q-mb-md">
      {{ meta_field.label }} <span class="text-red">&nbsp;{{ asterisk }}</span>
    </div>
    <div class="q-gutter-sm q-pt-md">
      <template v-for="option in options" :key="option.value">
        <q-radio
          v-model="model"
          dense
          :disable="readonly"
          :val="option.value"
          :label="option.label"
          @update:model-value="emit('update:modelValue', $event)"
        />
      </template>
    </div>
  </div>
</template>

<script setup lang="ts">
import type { OptionMetaField } from 'src/supplier/types/meta';
import { computed, ref } from 'vue';
import { RegisterStep, MetaKeys } from 'src/supplier/types';
import { QOptionGroupProps } from 'quasar';

type RadioFieldProp = {
  meta_field: OptionMetaField;
  name: string;
  type: QOptionGroupProps['type'];
  label?: string;
  rules: OptionMetaField['rules'];
  class?: string;
  disable: OptionMetaField['disable'];
  readonly: boolean;
  modelValue: any;
  stackLabel: boolean;
  dense: boolean;
  hideBottomSpace: boolean;
  reactiveRule?: boolean;
  asterisk?: string;
  labelSlot?: boolean;
  isOuter?: boolean;
};

const props = defineProps<RadioFieldProp>();
const emit = defineEmits(['update:modelValue']);
 
const { meta_field } = props;
const model = ref(props.modelValue);
const additionalClass = 'q-col-gutter-xl';
const options = computed(() => {
  return meta_field.options?.map((option) => {
    return {
      label: option.label,
      value: option.value,
    };
  });
});
</script>
